      blogId: BLOG_ID,
      resource: {
        title: post.title,
        content: post.content,
        labels: post.labels,
        published: new Date().toISOString()
      },
    });

    return {
      success: true,
      url: res.data.url,
      id: res.data.id,
      title: post.title
    };
  } catch (err) {
    return {
      success: false,
      error: err.message,
      title: post.title
    };
  }
}

